import itertools,json
optsA=['KMP','LNP','KLN','MQR','LMQ']
optsB=['LPQ','NPR','LMP','MNR','KNP']
daysA=[{2,7},{1,6,7},{7},{8},{2,7}]
daysB=[{4,6},{3},{2,8},{3},{6,7,8}]
feasible=[]
for a in itertools.product(*optsA):
    if a[0]!='M' or len(set(a))!=5: continue
    for b in itertools.product(*optsB):
        if len(set(b))!=5 or a[1]!=b[3]: continue
        shared=set(a)&set(b)
        if len(shared)!=3 or len(shared&set('KPR'))!=1: continue
        attendance={p:set() for p in 'KLMNPQR'}
        for assignment,days in [(a,daysA),(b,daysB)]:
            for p,d in zip(assignment,days): attendance[p]|=d
        score=sum(len(d)>=3 for d in attendance.values())
        feasible.append((score,''.join(a),''.join(b)))
lo=min(x[0] for x in feasible); hi=max(x[0] for x in feasible)
def witness(score):
    _,a,b=next(x for x in feasible if x[0]==score)
    return {'A':a,'B':b}
result={'feasible_linkages':len(feasible),'bounds':[lo,hi],'low_witness':witness(lo),'high_witness':witness(hi),'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
# Verify tightened facts distinguish this run, and check witnesses by independent day scanning.
assert all(a[0]=='M' and a[1]==b[3]=='N' for _,a,b in feasible)
for target,key in [(lo,'low_witness'),(hi,'high_witness')]:
    w=result[key]
    scores=[]
    for p in 'KLMNPQR':
        credited={d for label,days in [('A',daysA),('B',daysB)] for i,ds in enumerate(days) for d in ds if w[label][i]==p}
        scores.append(len(credited)>=3)
    assert sum(scores)==target
print(json.dumps(result))
print('scores:',{n:sum(x[0]==n for x in feasible) for n in range(lo,hi+1)})

